#!/usr/bin/env python3
"""Deterministic, offline and deliberately non-promotional MINT storyboard."""
import argparse, hashlib, html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]; SOURCE=ROOT/'product/mint_next/storyboard/three_a.storyboard.json'; OUTPUT=ROOT/'product/mint_next/storyboard/index.html'
def e(x): return html.escape(str(x),quote=True)
def phase(data,root):
    p=root/data['phase_authority']['path']; text=p.read_text(); m=re.match(r'Status: `([a-z_]+)`$',data['phase_authority']['status_anchor']); return m.group(1) if m and data['phase_authority']['status_anchor'] in text else 'inconnu'
def axes(data):
    ss=data['scenes']; ios=all(any(r['platform']=='ios' for r in x['evidence']['runtime_receipts']) for x in ss); android=all(any(r['platform']=='android' for r in x['evidence']['runtime_receipts']) for x in ss)
    accessible=all(x['evidence']['code_refs'] and x['evidence']['runtime_receipts'] for x in ss); novice=data['novice_validation']['status']=='passed' and len(data['novice_validation']['observations'])>=2
    show=ios and android and accessible and novice and all(x['evidence']['exposure_receipts'] for x in ss)
    return [('Cible','définie, non prouvée','neutral'),('Accessible','aucune preuve app' if not accessible else 'atteignable','neutral' if not accessible else 'pass'),('Novices','non testé' if not novice else 'testé','neutral' if not novice else 'pass'),('iOS','aucune preuve' if not ios else 'prouvé','neutral' if not ios else 'pass'),('Android','aucune preuve' if not android else 'prouvé','neutral' if not android else 'pass'),('Montrable','bloqué' if not show else 'autorisé','blocked' if not show else 'pass')]
def human_summary(values):
    state={name:value for name,value,_ in values}; parts=['Cible conçue sur le papier.']
    if state['Accessible']!='atteignable': parts.append("Aucun parcours n’est prouvé atteignable dans l’app.")
    if state['iOS']!='prouvé' and state['Android']!='prouvé': parts.append('Aucun écran runtime iOS ou Android n’est prouvé.')
    if state['Novices']!='testé': parts.append("Rien n’a été testé avec des novices.")
    if state['Montrable']!='autorisé': parts.append("Rien n’est montrable.")
    return ' '.join(parts)
def wireframe(s):
    human={'today_opportunity':'Année 2026 · Situation à vérifier','facts_review':'Domicile confirmé · Versements à vérifier','confirm_fact':'Montant proposé · Source · Période','safe_refusal':'Aucune donnée ne sera enregistrée','calculate':'Hypothèses visibles · Estimation encadrée','explain_result':'Versé · Impôts · Liquidité · Retrait','free_choice':'CHF 0 ou montant choisi librement','plan_confirmation':'Montant · Échéance · Prochaine action','return_today':'Décision retrouvable dans Ma situation'}[s['id']]
    return f'''<div class="phone" aria-label="Maquette mobile cible : {e(s['title'])}"><div class="notch"></div><div class="mock-label">MAQUETTE · PAS LE PRODUIT</div><div class="phone-head"><span aria-hidden="true">←</span><b>MINT</b><span aria-hidden="true">•••</span></div><div class="mock-body"><span class="eyebrow">{e(s['chapter'])}</span><h4>{e(s['title'])}</h4><p>{e(s['user_sees'])}</p><div class="fact-row"><i aria-hidden="true"></i><span>{e(human)}</span></div><span class="mock-cta" aria-hidden="true">{e(s['primary_action'])}</span><small>Élément illustratif, non interactif</small></div></div>'''
def dossier(s):
    ev=s['evidence']; limitations=[]
    if not ev['code_refs']: limitations.append('Aucun code vérifié')
    if not ev['runtime_receipts']: limitations.append('Aucune observation iOS ou Android')
    if not ev['exposure_receipts']: limitations.append('Exposition interdite')
    transitions=' · '.join(f'{e(t["event"])} → {e(t["destination"])}' for t in s['transitions']) or 'Terminal sûr'
    return f'''<article class="proof-card"><header><span class="dot neutral" aria-hidden="true"></span><div><small>{e(s['chapter'])}</small><h3>{e(s['title'])}</h3></div></header><dl><dt>Cible — intention</dt><dd>{e(s['target']['intention_oracle'])}</dd><dt>Critère d’observation attendu</dt><dd>{e(s['target']['observation_oracle'])}</dd><dt>Observé</dt><dd>Aucune observation recevable</dd><dt>Route · état</dt><dd><code>{e(s['architecture']['route'])}</code> · <code>{e(s['architecture']['state'])}</code></dd><dt>Transitions</dt><dd>{transitions}</dd><dt>Écritures cibles</dt><dd>{e(', '.join(s['data']['writes']) or 'Aucune')}</dd><dt>Limites actuelles</dt><dd>{e(' · '.join(limitations))}</dd></dl></article>'''
def scene_card(s,n):
    return f'''<article class="comic"><div class="comic-top"><span class="number">{n:02}</span><div><small>{e(s['chapter'])}</small><h3>{e(s['title'])}</h3></div></div>{wireframe(s)}<div class="caption"><b>Ce que la personne doit comprendre</b><p>{e(s['user_understands'])}</p><b>Pourquoi cette scène existe</b><p>{e(s['summary'])}</p></div></article>'''
def render(data,root=ROOT):
    by={s['id']:s for s in data['scenes']}; ax=axes(data)
    axis_html=''.join(f'<li class="axis {c}"><span class="dot {c}" aria-hidden="true"></span><b>{e(n)}</b><span>{e(v)}</span></li>' for n,v,c in ax)
    happy=[]
    for i,sid in enumerate(data['happy_path'],1):
        happy.append(scene_card(by[sid],i))
        if i<len(data['happy_path']): happy.append('<div class="arrow" aria-hidden="true">↓</div>')
    labels={'missing_data':'Donnée manquante','refusal':'Refus d’enregistrer','zero_choice':'Choisir CHF 0'}; branch=[]
    for key,path in data['branches'].items():
        unique=[]
        for sid in path:
            if sid not in data['happy_path'] and sid not in unique: unique.append(sid)
        if not unique: unique=[path[-1]]
        cards=''.join(scene_card(by[sid],i+1) for i,sid in enumerate(unique))
        branch.append(f'<section class="branch"><h3>{labels[key]}</h3><p class="route">{" → ".join(e(by[s]["title"]) for s in path)}</p><div class="branch-grid">{cards}</div></section>')
    proofs=''.join(dossier(s) for s in data['scenes'])
    decisions=''.join(f'''<article class="proof-card"><small>{e(d['id'])} · discussion</small><h3>{e(d['question'])}</h3><p><b>Décision</b><br>{e(d['decision'])}</p><p><b>Pourquoi</b><br>{e(d['rationale'])}</p><p><b>Alternative rejetée</b><br>{e(d['rejected'])}</p><p><b>À rouvrir lorsque</b><br>{e(d['revisited_when'])}</p></article>''' for d in data['decisions'])
    p=phase(data,root)
    human=human_summary(ax)
    return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><meta name="viewport" content="width=device-width, initial-scale=1"><title>MINT Storyboard — {e(data['goal']['title'])}</title><style>
:root{{--ink:#0a0a0a;--soft:rgba(10,10,10,.64);--mute:rgba(10,10,10,.42);--line:rgba(10,10,10,.1);--paper:#f7f5ee;--surface:#fff;--mint:#9ee5c5;--deep:#1c8466;--danger:#b8442a;--ui:'PP Neue Montreal','Neue Haas Grotesk','Inter',-apple-system,system-ui,sans-serif;--display:'PP Editorial New','GT Sectra','Canela','Times New Roman',serif}}*{{box-sizing:border-box}}html{{font-size:100%}}body{{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 var(--ui)}}main{{max-width:1120px;margin:auto;padding:24px 20px 80px}}a{{color:var(--deep);text-underline-offset:4px}}a:focus-visible,summary:focus-visible{{outline:3px solid var(--deep);outline-offset:4px;border-radius:4px}}.hero{{background:var(--ink);color:white;padding:40px;border-radius:20px}}.hero h1{{font:italic 400 clamp(2.4rem,7vw,4.8rem)/.96 var(--display);letter-spacing:-.03em;margin:.2em 0}}.hero p{{max-width:780px;color:#f7f5eed0}}.truth{{font-size:clamp(1.15rem,3vw,1.55rem);color:white!important;font-weight:600}}.axes{{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:#ffffff24;border:1px solid #ffffff24;padding:0;list-style:none;margin:28px 0 0}}.axis{{display:flex;min-height:82px;flex-direction:column;gap:3px;padding:14px;background:#151515}}.axis span:last-child{{color:#ddd;font-size:.82rem}}.dot{{width:10px;height:10px;border-radius:50%;display:inline-block;background:#aaa}}.dot.blocked{{background:#f09a80}}.dot.pass{{background:var(--mint)}}nav{{display:flex;gap:20px;padding:24px 4px}}h2{{font-size:1.8rem;margin-top:56px}}h3,h4{{font-weight:500}}.intro{{max-width:720px;color:var(--soft)}}.comic-flow{{display:grid;grid-template-columns:1fr;gap:12px;max-width:760px;margin:auto}}.comic{{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:20px;display:grid;grid-template-columns:minmax(230px,310px) 1fr;gap:24px}}.comic-top{{grid-column:1/-1;display:flex;gap:12px;align-items:center}}.comic h3{{margin:0}}.number{{display:grid;place-items:center;width:42px;height:42px;border-radius:50%;background:var(--mint);font-weight:700}}small,.eyebrow{{text-transform:uppercase;letter-spacing:.14em;font-size:10px;color:var(--deep)}}.phone{{width:min(100%,280px);min-height:490px;border:8px solid var(--ink);border-radius:34px;background:var(--paper);padding:10px;position:relative;margin:auto;box-shadow:0 12px 30px #0a0a0a18}}.notch{{width:74px;height:17px;background:var(--ink);border-radius:0 0 12px 12px;margin:-10px auto 7px}}.mock-label{{background:#fff1ca;color:#684d00;text-align:center;font-size:9px;font-weight:800;padding:4px;border-radius:6px}}.phone-head{{display:flex;justify-content:space-between;padding:16px 5px}}.mock-body{{background:white;border-radius:18px;padding:18px;min-height:380px;display:flex;flex-direction:column}}.mock-body h4{{font:italic 400 28px/1.02 var(--display);margin:10px 0}}.fact-row{{display:flex;gap:8px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:14px 0;margin:12px 0}}.fact-row i{{width:10px;height:10px;border-radius:50%;background:var(--mint);margin-top:6px}}.mock-cta{{margin-top:auto;text-align:center;background:var(--deep);color:white;border-radius:12px;padding:12px;font-weight:700}}.mock-body>small{{text-align:center;color:var(--mute);margin-top:7px;text-transform:none;letter-spacing:0}}.caption{{align-self:center}}.caption p{{color:var(--soft)}}.arrow{{font-size:2rem;text-align:center;color:var(--deep)}}.branch{{margin-top:24px;background:#efece3;padding:20px;border-radius:20px}}.branch h3{{margin-bottom:0}}.route{{color:var(--soft)}}.branch-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px}}.branch .comic{{display:block}}.branch .caption{{margin-top:18px}}.proof-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px}}.proof-card{{background:white;border:1px solid var(--line);border-radius:16px;padding:18px}}.proof-card header{{display:flex;gap:10px;align-items:start}}.proof-card h3{{margin:0}}dt{{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--mute);margin-top:12px}}dd{{margin:2px 0}}code{{overflow-wrap:anywhere}}.novice{{border-left:5px solid #d7a23a;background:#fff8df;padding:18px;border-radius:0 14px 14px 0}}footer{{border-top:1px solid var(--line);margin-top:50px;padding-top:20px}}@media(max-width:700px){{.axes{{grid-template-columns:1fr 1fr}}.comic{{grid-template-columns:1fr}}}}@media(max-width:360px){{main{{padding-inline:10px}}.hero{{padding:22px 16px}}.axes{{grid-template-columns:1fr}}.comic{{padding:12px}}.phone{{min-height:440px}}}}@media(prefers-reduced-motion:reduce){{*{{scroll-behavior:auto!important;transition:none!important;animation:none!important}}}}
</style></head><body><main><header class="hero" id="atlas"><small>Atlas · {e(data['generated_at'])}</small><h1>{e(data['goal']['title'])}</h1><p>{e(data['goal']['promise'])}</p><p class="truth">{e(human)}</p><p>Statut résolu depuis le SPEC piné : <code>{e(p)}</code>. Aucun statut n’est saisi dans ce HTML.</p><ul class="axes" aria-label="Axes indépendants de preuve">{axis_html}</ul></header><nav aria-label="Niveaux du storyboard"><a href="#atlas">Atlas</a><a href="#episode">Épisode</a><a href="#dossier">Dossier</a></nav><section id="episode"><h2>Épisode — l’histoire cible</h2><p class="intro">Une bande dessinée de navigation, pas une capture de l’application. Les téléphones portent tous le marquage MAQUETTE.</p><div class="comic-flow">{''.join(happy)}</div><h2>Et si…</h2>{''.join(branch)}</section><section id="dossier"><h2>Dossier — technique, preuves et limites</h2><p class="intro">La cible et l’observation sont séparées. Un critère attendu ne constitue jamais une preuve.</p><div class="novice"><b>Test novice : non exécuté</b><p>Contrat prévu : 2 lecteurs, 5 questions, 60 secondes. Résultats actuels : 0 lecteur, 0 observation. Ce protocole ne promeut aucun axe.</p></div><h2>Décisions et discussion</h2><div class="proof-grid">{decisions}</div><h2>Scènes et preuves</h2><div class="proof-grid">{proofs}</div></section><footer><b>Ce que Julien doit tester maintenant</b><p>Rien. Ce document permet d’abord de discuter l’histoire cible ; il ne certifie aucun écran.</p><p>Autorité visuelle : <code>tokens.jsx</code> · Révision {e(data['design_authority']['approved_revision'])}. <code>DESIGN_SYSTEM.md</code> est un contexte historique, non concurrent.</p><p>Fontes hors ligne : PP Neue Montreal → Neue Haas Grotesk → Inter → fonte système ; PP Editorial New → GT Sectra → Canela → Times New Roman. Aucune fonte n’est embarquée ou chargée par le réseau.</p></footer></main></body></html>'''
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--check',action='store_true'); ap.add_argument('--output',type=Path,default=OUTPUT); a=ap.parse_args(); raw=render(json.loads(SOURCE.read_text()),ROOT).encode()
    if a.check:
        if not a.output.exists() or a.output.read_bytes()!=raw: raise SystemExit('STALE: regenerate storyboard HTML')
        print('OK mint_storyboard_render')
    else: a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_bytes(raw)
if __name__=='__main__': main()
